const cluster = $input.item.json;
const PRODUCTOS = $('Definir Clusters y Productos').item.json.PRODUCTOS;
const { pillar, articulos, color, emoji } = cluster;

const buildBanner = (prod) => `
<div style="background:linear-gradient(${color.grad});border-radius:12px;padding:0;margin:32px 0;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,.12);font-family:Arial,sans-serif;max-width:700px">
  <div style="display:flex;align-items:stretch;flex-wrap:wrap">
    <img src="${prod.imagen}" alt="${prod.nombre}" style="width:140px;object-fit:cover;flex-shrink:0">
    <div style="flex:1;min-width:180px;padding:18px;display:flex;flex-direction:column;justify-content:center">
      <p style="color:rgba(255,255,255,.8);font-size:10px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin:0 0 5px">${prod.tipo} ${emoji}</p>
      <h3 style="color:#fff;font-size:16px;font-weight:800;margin:0 0 8px;line-height:1.3">${prod.nombre}</h3>
      <a href="${prod.link}" target="_blank" rel="noopener sponsored"
         style="display:inline-block;background:#fff;color:${color.text};font-weight:800;font-size:12px;padding:9px 18px;border-radius:7px;text-decoration:none;align-self:flex-start">
        Ver ahora →
      </a>
    </div>
  </div>
  <p style="color:rgba(255,255,255,.4);font-size:9px;text-align:right;padding:3px 12px;margin:0">*Enlace de afiliado</p>
</div>`;

// TOC links
const tocLinks = articulos.map(a =>
  `<li style="margin:5px 0"><a href="/p/${a.slug}.html" style="color:${color.text};text-decoration:none;font-size:14px">→ ${a.titulo}</a></li>`
).join('\n');

// Productos únicos para el pillar (sin duplicados)
const productosUsados = [...new Set(articulos.map(a => a.producto))];
const primerProducto = PRODUCTOS[productosUsados[0]];

const htmlPillar = `<!-- PÁGINA PILAR: ${pillar.titulo} -->
<article style="max-width:820px;margin:0 auto;font-family:Arial,sans-serif;line-height:1.7;color:#333">

  <h1 style="font-size:28px;font-weight:800;color:#1a1a1a;margin:0 0 10px">${pillar.titulo}</h1>
  <p style="color:#666;font-size:16px;margin:0 0 28px;line-height:1.6">${pillar.descripcion}</p>

  <!-- BANNER PRODUCTO PRINCIPAL -->
  ${buildBanner(primerProducto)}

  <!-- TABLA DE CONTENIDOS -->
  <div style="background:${color.bg};border-left:4px solid ${color.text};border-radius:8px;padding:18px 22px;margin:28px 0">
    <h2 style="font-size:16px;font-weight:700;color:#1a1a1a;margin:0 0 10px">${emoji} En esta guía encontrarás:</h2>
    <ol style="margin:0;padding-left:18px">${tocLinks}</ol>
  </div>

  <!-- INTRO (editar según el artículo) -->
  <h2 style="font-size:22px;font-weight:700;color:#1a1a1a;margin:36px 0 12px">¿Por qué es importante este tema?</h2>
  <p style="font-size:16px;color:#444">[Escribe aquí la introducción de tu página pilar. Mínimo 300 palabras para SEO óptimo.]</p>

  <!-- GRID DE ARTÍCULOS DEL CLUSTER -->
  <h2 style="font-size:22px;font-weight:700;color:#1a1a1a;margin:40px 0 16px">Artículos completos del cluster</h2>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:14px;margin-bottom:40px">
    ${articulos.map(a => {
      const prod = PRODUCTOS[a.producto];
      return `<a href="/p/${a.slug}.html"
         style="display:block;background:#fff;border:1px solid #e0e0e0;border-radius:10px;overflow:hidden;text-decoration:none;transition:box-shadow .2s"
         onmouseover="this.style.boxShadow='0 4px 14px rgba(0,0,0,.1)'" onmouseout="this.style.boxShadow='none'">
        <img src="${prod.imagen}" alt="" style="width:100%;height:120px;object-fit:cover">
        <div style="padding:12px">
          <p style="color:${color.text};font-size:11px;font-weight:700;text-transform:uppercase;margin:0 0 4px">${emoji} ${prod.tipo}</p>
          <p style="color:#1a1a1a;font-weight:700;font-size:14px;margin:0;line-height:1.3">${a.titulo}</p>
        </div>
      </a>`;
    }).join('')}
  </div>

  <!-- BANNER FINAL -->
  ${buildBanner(primerProducto)}

</article>
<!-- FIN PÁGINA PILAR: ${pillar.slug} -->`;

return [{
  json: {
    nicho: cluster.nicho,
    tipo: 'pillar',
    slug: pillar.slug,
    titulo: pillar.titulo,
    html: htmlPillar
  }
}];

const cluster = $input.item.json;
const PRODUCTOS = $('Definir Clusters y Productos').item.json.PRODUCTOS;
const { pillar, articulos, color, emoji } = cluster;

return articulos.map(articulo => {
  const prod = PRODUCTOS[articulo.producto];

  const html = `<!-- SNIPPET CLUSTER para: ${articulo.titulo} -->

<!-- Breadcrumb al Pilar -->
<div style="background:${color.bg};border-left:4px solid ${color.text};border-radius:8px;padding:12px 16px;margin:24px 0;font-family:Arial,sans-serif">
  <p style="margin:0;font-size:13px;color:#666">Parte de la guía completa:</p>
  <a href="/p/${pillar.slug}.html" style="color:${color.text};font-weight:700;font-size:14px;text-decoration:none">
    ${emoji} ${pillar.titulo} →
  </a>
</div>

<!-- Banner Hotmart con imagen -->
<div style="background:linear-gradient(${color.grad});border-radius:14px;padding:0;margin:40px 0;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,.12);font-family:Arial,sans-serif;max-width:700px">
  <div style="display:flex;align-items:stretch;flex-wrap:wrap">
    <img src="${prod.imagen}" alt="${prod.nombre}" style="width:150px;height:auto;object-fit:cover;flex-shrink:0">
    <div style="flex:1;min-width:180px;padding:20px;display:flex;flex-direction:column;justify-content:center">
      <p style="color:rgba(255,255,255,.8);font-size:10px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin:0 0 5px">${prod.tipo} recomendado ${emoji}</p>
      <h3 style="color:#fff;font-size:17px;font-weight:800;margin:0 0 8px;line-height:1.3">${prod.nombre}</h3>
      <p style="color:rgba(255,255,255,.85);font-size:13px;margin:0 0 14px">Aprende paso a paso y domina el tema.</p>
      <a href="${prod.link}" target="_blank" rel="noopener sponsored"
         style="display:inline-block;background:#fff;color:${color.text};font-weight:800;font-size:13px;padding:10px 20px;border-radius:8px;text-decoration:none;align-self:flex-start">
        Ver ahora →
      </a>
    </div>
  </div>
  <p style="color:rgba(255,255,255,.35);font-size:9px;text-align:right;padding:3px 12px;margin:0">*Enlace de afiliado · Sin costo extra para ti</p>
</div>
<!-- FIN SNIPPET -->`;

  return {
    json: {
      nicho: cluster.nicho,
      tipo: 'cluster-snippet',
      pillarSlug: pillar.slug,
      slug: articulo.slug,
      titulo: articulo.titulo,
      productoId: articulo.producto,
      html
    }
  };
});

const todos = $input.all();
const pilar   = todos.filter(i => i.json.tipo === 'pillar').length;
const cluster = todos.filter(i => i.json.tipo === 'cluster-snippet').length;
console.log(`✅ ${pilar} páginas pilar + ${cluster} artículos cluster generados`);
return [{ json: { pillarGenerados: pilar, clusterGenerados: cluster, total: todos.length, timestamp: new Date().toISOString() } }];
